<!-- Section 5: Operational Directives Banner (General User Access) -->
<div class="grid grid-cols-1 md:grid-cols-3 gap-space-md pt-space-xs">
    <div class="bg-white p-space-md border-l-4 border-primary shadow-sm flex items-start gap-space-sm">
        <span class="material-symbols-outlined text-primary text-[22px] shrink-0 mt-0.5">shield_person</span>
        <div>
            <h2 class="text-xs text-primary uppercase font-bold tracking-wider">
                General Staff Access Scope
            </h2>
            <p class="text-xs text-mute mt-1 leading-relaxed">
                This directory lists approved Indirect (Non-Production) and Subcontractor vendors with general identity,
                location, and liaison contact information only.
            </p>
        </div>
    </div>
    <div class="bg-white p-space-md border-l-4 border-secondary shadow-sm flex items-start gap-space-sm">
        <span class="material-symbols-outlined text-secondary text-[22px] shrink-0 mt-0.5">add_business</span>
        <div>
            <h2 class="text-xs text-primary uppercase font-bold tracking-wider">
                Need a New Vendor?
            </h2>
            <p class="text-xs text-mute mt-1 leading-relaxed">
                If your required supplier is not listed here, submit a New Vendor Requisition (PUR-NVF) form through
                Webflow for Purchasing evaluation and registration.
            </p>
        </div>
    </div>
    <div class="bg-white p-space-md border-l-4 border-error shadow-sm flex items-start gap-space-sm">
        <span class="material-symbols-outlined text-accent text-[22px] shrink-0 mt-0.5">support_agent</span>
        <div>
            <h2 class="text-xs text-primary uppercase font-bold tracking-wider">
                Information Updates
            </h2>
            <p class="text-xs text-mute mt-1 leading-relaxed">
                To update vendor contact details, address, or status, please contact your assigned Procurement Buyer
                (PAD / SC Section) to initiate a Cover Sheet update.
            </p>
        </div>
    </div>
</div>
